using System;
using UnityEngine;
using UnityEngine.Tilemaps;
using Framework.Grid;
using Framework.Tilemap;
using Game.Map;

namespace Game.Stage
{
    #region Stage State

    /// <summary>
    /// ステージの進行状態を表す列挙型。
    /// </summary>
    public enum MazeStageState
    {
        None,       // 未生成
        Generating, // 生成中
        Ready,      // 開始待機
        Playing,    // プレイ中
        Paused,     // 一時停止中
        Cleared,    // クリア
        Failed      // 失敗
    }

    #endregion

    /// <summary>
    /// 迷路ステージ全体の生成、描画、進行を管理する。
    ///
    /// キャラクターの移動やAIなどは担当せず、
    /// 外部システムから操作される管理クラスとして機能する。
    /// </summary>
    [DisallowMultipleComponent]
    public class MazeStageManager : MonoBehaviour
    {
        #region Inspector Fields

        [Header("ステージ生成設定")]

        /// <summary>
        /// ステージの生成条件。
        /// </summary>
        [SerializeField]
        private MazeStageGenerationSettings settings =
            new MazeStageGenerationSettings();

        /// <summary>
        /// シーン開始時にステージを生成するか。
        /// </summary>
        [SerializeField]
        private bool generateOnStart = true;

        /// <summary>
        /// ステージ生成後に自動でプレイを開始するか。
        /// </summary>
        [SerializeField]
        private bool autoStartStage = false;

        [Header("座標変換設定")]

        /// <summary>
        /// グリッド座標とワールド座標の変換システム。
        /// </summary>
        [SerializeField]
        private GridCoordinateConverter coordinateConverter;

        [Header("Tilemap設定")]

        /// <summary>
        /// 床の描画先。
        /// </summary>
        [SerializeField]
        private Tilemap floorTilemap;

        /// <summary>
        /// 壁の描画先。
        /// </summary>
        [SerializeField]
        private Tilemap wallTilemap;

        [Header("タイル設定")]

        /// <summary>
        /// 床の描画に使用するタイル。
        /// </summary>
        [SerializeField]
        private TileBase floorTile;

        /// <summary>
        /// 通常の壁の描画に使用するタイル。
        /// </summary>
        [SerializeField]
        private TileBase wallTile;

        /// <summary>
        /// 破壊可能な壁の描画に使用するタイル。
        /// 未設定の場合は通常の壁を使用する。
        /// </summary>
        [SerializeField]
        private TileBase breakableWallTile;

        [Header("実体生成設定")]

        /// <summary>
        /// キャラクターや配置物を生成するシステム。
        /// 未設定の場合はデータとTilemapのみ生成する。
        /// </summary>
        [SerializeField]
        private MazeStageSpawner stageSpawner;

        #endregion

        #region Runtime Fields

        /// <summary>
        /// 現在のステージ生成結果。
        /// </summary>
        private MazeStageGenerationResult stageResult;

        /// <summary>
        /// Tilemap描画システム。
        /// </summary>
        private GridTilemapRenderer<MazeCell> mapRenderer;

        /// <summary>
        /// 現在のステージ状態。
        /// </summary>
        private MazeStageState state = MazeStageState.None;

        /// <summary>
        /// 現在の残り宝石数。
        /// </summary>
        private int remainingGemCount;

        /// <summary>
        /// 現在の残りアイテム数。
        /// </summary>
        private int remainingItemCount;

        /// <summary>
        /// プレイ開始からの経過時間（秒）。
        /// </summary>
        private float elapsedTime;

        #endregion

        #region Properties

        /// <summary>
        /// 現在のステージ状態。
        /// </summary>
        public MazeStageState State => state;

        /// <summary>
        /// 現在のステージ生成結果。
        /// </summary>
        public MazeStageGenerationResult StageResult =>
            stageResult;

        /// <summary>
        /// 現在の迷路マップ。
        /// 未生成の場合はnullを返す。
        /// </summary>
        public GridMap<MazeCell> Map =>
            stageResult?.Map;

        /// <summary>
        /// 現在のステージが生成済みか。
        /// </summary>
        public bool HasStage => stageResult != null;

        /// <summary>
        /// 現在プレイ中か。
        /// </summary>
        public bool IsPlaying =>
            state == MazeStageState.Playing;

        /// <summary>
        /// 現在の残り宝石数。
        /// </summary>
        public int RemainingGemCount =>
            remainingGemCount;

        /// <summary>
        /// 現在の残りアイテム数。
        /// </summary>
        public int RemainingItemCount =>
            remainingItemCount;

        /// <summary>
        /// ステージ生成時の宝石数。
        /// </summary>
        public int InitialGemCount =>
            stageResult?.InitialGemCount ?? 0;

        /// <summary>
        /// 取得済みの宝石数。
        /// </summary>
        public int CollectedGemCount =>
            InitialGemCount - RemainingGemCount;

        /// <summary>
        /// プレイ開始からの経過時間（秒）。
        /// </summary>
        public float ElapsedTime => elapsedTime;

        /// <summary>
        /// 宝石の取得進捗率（0～1）。
        /// </summary>
        public float Progress
        {
            get
            {
                if (!HasStage)
                {
                    return 0f;
                }

                if (InitialGemCount == 0)
                {
                    return 1f;
                }

                return Mathf.Clamp01(
                    (float)CollectedGemCount /
                    InitialGemCount);
            }
        }

        /// <summary>
        /// 座標変換システム。
        /// </summary>
        public GridCoordinateConverter CoordinateConverter =>
            coordinateConverter;

        #endregion

        #region Events

        /// <summary>
        /// ステージ状態が変化した際の通知。
        /// 引数：変更前の状態、変更後の状態。
        /// </summary>
        public event Action<MazeStageState, MazeStageState>
            StateChanged;

        /// <summary>
        /// ステージ生成完了時の通知。
        /// 引数：生成結果。
        /// </summary>
        public event Action<MazeStageGenerationResult>
            StageGenerated;

        /// <summary>
        /// ステージ開始時の通知。
        /// </summary>
        public event Action StageStarted;

        /// <summary>
        /// 宝石残数が変化した際の通知。
        /// 引数：変更後の残数。
        /// </summary>
        public event Action<int> GemCountChanged;

        /// <summary>
        /// アイテム残数が変化した際の通知。
        /// 引数：変更後の残数。
        /// </summary>
        public event Action<int> ItemCountChanged;

        /// <summary>
        /// 宝石取得時の通知。
        /// 引数：取得した宝石の座標。
        /// </summary>
        public event Action<Vector2Int> GemCollected;

        /// <summary>
        /// アイテム取得時の通知。
        /// 引数：取得したアイテムの座標。
        /// </summary>
        public event Action<Vector2Int> ItemCollected;

        /// <summary>
        /// 壁破壊時の通知。
        /// 引数：破壊した壁の座標。
        /// </summary>
        public event Action<Vector2Int> WallDestroyed;

        /// <summary>
        /// ステージクリア時の通知。
        /// 引数：クリアタイム（秒）。
        /// </summary>
        public event Action<float> StageCleared;

        /// <summary>
        /// ステージ失敗時の通知。
        /// </summary>
        public event Action StageFailed;

        #endregion

        #region Unity Methods

        /// <summary>
        /// シーン開始時の処理。
        /// </summary>
        private void Start()
        {
            if (generateOnStart)
            {
                GenerateStage();
            }
        }

        /// <summary>
        /// 毎フレームのステージ進行処理。
        /// </summary>
        private void Update()
        {
            // プレイ中のみ時間を計測する。
            if (IsPlaying)
            {
                elapsedTime += Time.deltaTime;
            }
        }

        /// <summary>
        /// オブジェクト破棄時の後処理。
        /// </summary>
        private void OnDestroy()
        {
            ReleaseStage();
        }

        #endregion

        #region Generation Methods

        /// <summary>
        /// Inspectorで指定された設定から
        /// ステージを生成する。
        /// </summary>
        /// <returns>生成に成功した場合はtrue</returns>
        public bool GenerateStage()
        {
            return GenerateStage(settings);
        }

        /// <summary>
        /// 指定された設定からステージを生成する。
        /// </summary>
        /// <param name="generationSettings">生成設定</param>
        /// <returns>生成に成功した場合はtrue</returns>
        public bool GenerateStage(
            MazeStageGenerationSettings generationSettings)
        {
            if (!Application.isPlaying ||
                state == MazeStageState.Generating)
            {
                return false;
            }

            if (!ValidateReferences())
            {
                return false;
            }

            ChangeState(MazeStageState.Generating);

            try
            {
                // 新しいステージデータを生成する。
                MazeStageGenerationResult newResult =
                    MazeStageGenerator.Generate(
                        generationSettings);

                // 以前のステージを解放する。
                ReleaseStage();

                // 新しいステージ情報を保持する。
                stageResult = newResult;

                remainingGemCount =
                    stageResult.InitialGemCount;

                remainingItemCount =
                    stageResult.InitialItemCount;

                elapsedTime = 0f;

                // マップの変更通知を購読する。
                Map.CellChanged += OnCellChanged;

                // Tilemapを描画する。
                RenderStage();

                // Prefabを生成する。
                if (stageSpawner != null)
                {
                    stageSpawner.SpawnStage(
                        stageResult,
                        coordinateConverter);
                }
            }
            catch (Exception exception)
            {
                ReleaseStage();

                ChangeState(MazeStageState.Failed);

                Debug.LogException(exception, this);

                StageFailed?.Invoke();

                return false;
            }

            ChangeState(MazeStageState.Ready);

            // 外部システムへ生成結果を通知する。
            StageGenerated?.Invoke(stageResult);

            GemCountChanged?.Invoke(remainingGemCount);
            ItemCountChanged?.Invoke(remainingItemCount);

            if (autoStartStage)
            {
                StartStage();
            }

            return true;
        }

        /// <summary>
        /// 現在のステージを解放して未生成状態に戻す。
        /// </summary>
        public void ClearStage()
        {
            if (state == MazeStageState.Generating)
            {
                return;
            }

            ReleaseStage();

            ChangeState(MazeStageState.None);
        }

        /// <summary>
        /// 現在のステージデータ、描画、配置物を解放する。
        /// </summary>
        private void ReleaseStage()
        {
            if (Map != null)
            {
                Map.CellChanged -= OnCellChanged;
            }

            if (stageSpawner != null)
            {
                stageSpawner.ClearStage();
            }

            if (mapRenderer != null)
            {
                mapRenderer.Clear();
                mapRenderer.Dispose();

                mapRenderer = null;
            }

            stageResult = null;

            remainingGemCount = 0;
            remainingItemCount = 0;
            elapsedTime = 0f;
        }

        /// <summary>
        /// 現在のマップをTilemapへ描画する。
        /// </summary>
        private void RenderStage()
        {
            floorTilemap.ClearAllTiles();
            wallTilemap.ClearAllTiles();

            mapRenderer =
                new GridTilemapRenderer<MazeCell>(Map);

            // 壁の下も含めて床を全面に描画する。
            mapRenderer.AddLayer(
                floorTilemap,
                (position, cell) => floorTile);

            // マスの地形に応じて壁を描画する。
            mapRenderer.AddLayer(
                wallTilemap,
                (position, cell) =>
                {
                    if (cell.IsBreakable)
                    {
                        return breakableWallTile != null
                            ? breakableWallTile
                            : wallTile;
                    }

                    return cell.IsWall
                        ? wallTile
                        : null;
                });

            mapRenderer.RenderAll();

            // Tilemapに実際に配置されたタイル数を確認する。
int floorCount = 0;
int wallCount = 0;

foreach (Vector2Int position in Map.GetPositions())
{
    Vector3Int cellPosition = new Vector3Int(
        position.x,
        position.y,
        0);

    if (floorTilemap.HasTile(cellPosition))
    {
        floorCount++;
    }

    if (wallTilemap.HasTile(cellPosition))
    {
        wallCount++;
    }
}

Debug.Log(
    "【Tilemap描画確認】\n" +
    $"マップサイズ：{Map.Width} × {Map.Height}\n" +
    $"床タイル数：{floorCount}\n" +
    $"壁タイル数：{wallCount}\n" +
    $"床の有効状態：{floorTilemap.gameObject.activeInHierarchy}\n" +
    $"壁の有効状態：{wallTilemap.gameObject.activeInHierarchy}",
    this);
        }

        #endregion

        #region State Methods

        /// <summary>
        /// ステージのプレイを開始する。
        /// </summary>
        /// <returns>開始に成功した場合はtrue</returns>
        public bool StartStage()
        {
            if (state != MazeStageState.Ready ||
                !HasStage)
            {
                return false;
            }

            elapsedTime = 0f;

            ChangeState(MazeStageState.Playing);

            StageStarted?.Invoke();

            // 宝石が0個のステージにも対応する。
            CheckClearCondition();

            return true;
        }

        /// <summary>
        /// ステージを一時停止する。
        /// </summary>
        /// <returns>一時停止に成功した場合はtrue</returns>
        public bool PauseStage()
        {
            if (!IsPlaying)
            {
                return false;
            }

            ChangeState(MazeStageState.Paused);

            return true;
        }

        /// <summary>
        /// 一時停止中のステージを再開する。
        /// </summary>
        /// <returns>再開に成功した場合はtrue</returns>
        public bool ResumeStage()
        {
            if (state != MazeStageState.Paused)
            {
                return false;
            }

            ChangeState(MazeStageState.Playing);

            CheckClearCondition();

            return true;
        }

        /// <summary>
        /// ステージを失敗状態にする。
        /// 敵との接触などの外部処理から呼び出す。
        /// </summary>
        /// <returns>状態変更に成功した場合はtrue</returns>
        public bool FailStage()
        {
            if (state != MazeStageState.Playing &&
                state != MazeStageState.Paused)
            {
                return false;
            }

            ChangeState(MazeStageState.Failed);

            StageFailed?.Invoke();

            return true;
        }

        /// <summary>
        /// ステージ状態を変更して外部へ通知する。
        /// </summary>
        /// <param name="newState">変更後の状態</param>
        private void ChangeState(MazeStageState newState)
        {
            if (state == newState)
            {
                return;
            }

            MazeStageState previousState = state;

            state = newState;

            StateChanged?.Invoke(
                previousState,
                newState);
        }

        /// <summary>
        /// ステージクリア条件を確認する。
        /// </summary>
        private void CheckClearCondition()
        {
            if (!IsPlaying || remainingGemCount > 0)
            {
                return;
            }

            ChangeState(MazeStageState.Cleared);

            StageCleared?.Invoke(elapsedTime);
        }

        #endregion

        #region Map Operation Methods

        /// <summary>
        /// 指定された座標が移動可能か確認する。
        /// </summary>
        /// <param name="position">確認する座標</param>
        /// <returns>移動可能な場合はtrue</returns>
        public bool IsWalkable(Vector2Int position)
        {
            return Map != null &&
                   Map.TryGetCell(
                       position,
                       out MazeCell cell) &&
                   cell.IsWalkable;
        }

        /// <summary>
        /// 指定された座標の宝石を取得する。
        /// </summary>
        /// <param name="position">宝石の座標</param>
        /// <returns>取得に成功した場合はtrue</returns>
        public bool TryCollectGem(Vector2Int position)
        {
            if (!IsPlaying ||
                Map == null ||
                !Map.TryGetCell(
                    position,
                    out MazeCell cell) ||
                !cell.HasGem)
            {
                return false;
            }

            // 宝石を取り除いた床データに変更する。
            MazeCell newCell =
                CreateEmptyCollectibleCell(cell);

            Map.SetCell(position, newCell);

            GemCollected?.Invoke(position);

            // 最後の宝石を取得した場合はクリアする。
            CheckClearCondition();

            return true;
        }

        /// <summary>
        /// 指定された座標のアイテムを取得する。
        /// </summary>
        /// <param name="position">アイテムの座標</param>
        /// <returns>取得に成功した場合はtrue</returns>
        public bool TryCollectItem(Vector2Int position)
        {
            if (!IsPlaying ||
                Map == null ||
                !Map.TryGetCell(
                    position,
                    out MazeCell cell) ||
                !cell.HasItem)
            {
                return false;
            }

            MazeCell newCell =
                CreateEmptyCollectibleCell(cell);

            Map.SetCell(position, newCell);

            ItemCollected?.Invoke(position);

            return true;
        }

        /// <summary>
        /// 取得物を取り除いた床データを生成する。
        ///
        /// 現在の配置仕様に基づき、
        /// アイテム配置候補属性を引き継ぐ。
        /// </summary>
        /// <param name="cell">取得前のマスデータ</param>
        /// <returns>取得物を取り除いたマスデータ</returns>
        private MazeCell CreateEmptyCollectibleCell(
            MazeCell cell)
        {
            MazeCell newCell = MazeCell.CreateFloor();

            if (cell.IsItemSpawn)
            {
                newCell = newCell.AddFlags(
                    MazeCellFlags.ItemSpawn);
            }

            return newCell;
        }

        /// <summary>
        /// 指定された座標の破壊可能な壁を破壊する。
        /// </summary>
        /// <param name="position">壁の座標</param>
        /// <returns>破壊に成功した場合はtrue</returns>
        public bool TryDestroyWall(Vector2Int position)
        {
            if (!IsPlaying ||
                Map == null ||
                !Map.TryGetCell(
                    position,
                    out MazeCell cell) ||
                !cell.IsBreakable)
            {
                return false;
            }

            // 壁を床へ変更する。
            // TilemapはCellChangedイベントによって更新される。
            Map.SetCell(
                position,
                MazeCell.CreateFloor());

            WallDestroyed?.Invoke(position);

            return true;
        }

        #endregion

        #region Event Methods

        /// <summary>
        /// マップのマスデータが変更された際の処理。
        /// 宝石数とアイテム数を差分更新する。
        /// </summary>
        /// <param name="position">変更された座標</param>
        /// <param name="previousCell">変更前のデータ</param>
        /// <param name="newCell">変更後のデータ</param>
        private void OnCellChanged(
            Vector2Int position,
            MazeCell previousCell,
            MazeCell newCell)
        {
            // 宝石の有無が変化した場合のみ更新する。
            if (previousCell.HasGem != newCell.HasGem)
            {
                remainingGemCount +=
                    newCell.HasGem ? 1 : -1;

                GemCountChanged?.Invoke(
                    remainingGemCount);
            }

            // アイテムの有無が変化した場合のみ更新する。
            if (previousCell.HasItem != newCell.HasItem)
            {
                remainingItemCount +=
                    newCell.HasItem ? 1 : -1;

                ItemCountChanged?.Invoke(
                    remainingItemCount);
            }
        }

        #endregion

        #region Validation Methods

        /// <summary>
        /// ステージ生成に必要な参照を検証する。
        /// </summary>
        /// <returns>参照が有効な場合はtrue</returns>
        private bool ValidateReferences()
        {
            if (coordinateConverter == null ||
                floorTilemap == null ||
                wallTilemap == null ||
                floorTile == null ||
                wallTile == null)
            {
                Debug.LogError(
                    "ステージ生成に必要な参照が不足しています。",
                    this);

                return false;
            }

            if (floorTilemap == wallTilemap)
            {
                Debug.LogError(
                    "床と壁には異なるTilemapを指定してください。",
                    this);

                return false;
            }

            return true;
        }

        #endregion
    }
}
